1	import { Controller, Get, Headers, NotFoundException, Param, Query } from '@nestjs/common';
2	import { SupabaseService } from '../supabase/supabase.service';
3	import { SupabaseJwtService } from '../auth/supabase-jwt.service';
4	import { RedisService } from '../redis/redis.service';
5	import { haversineKm } from '../common/geo.util';
6	import { normalizarDominio } from '../common/dominio.util';
7	import { CombosService } from '../combos/combos.service';
8	import * as os from 'os';
9	
10	const PRODUTO_FIELDS = 'id, name, description, price, preco_promo, image_url, category_id, restaurant_id, tags, destaque, is_active, quantidade_estoque';
11	const RAIO_KM_PADRAO = 15;
12	
13	// TTL curto: aceita alguns segundos de defasagem de estoque/preço no marketplace
14	// público em troca de menos carga no Supabase (mesmo trade-off que iFood/Rappi fazem).
15	const TTL_CARDAPIO = 15;
16	const TTL_FILTROS = 60;
17	
18	@Controller('r')
19	export class CatalogoController {
20	  constructor(
21	    private supabase: SupabaseService,
22	    private supabaseJwt: SupabaseJwtService,
23	    private combosService: CombosService,
24	    private redis: RedisService,
25	  ) {}
26	
27	  @Get('acesso')
28	  async getAcesso() {
29	    const nets = os.networkInterfaces();
30	    const todos: string[] = [];
31	    for (const iface of Object.values(nets)) {
32	      for (const net of iface ?? []) {
33	        if (net.family === 'IPv4' && !net.internal) todos.push(net.address);
34	      }
35	    }
36	    // Prioriza 192.168.x.x (WiFi doméstico/corporativo) e 10.x.x.x (redes corporativas).
37	    // Descarta 172.16-31.x.x que são WSL, Docker, Hyper-V — não acessíveis por dispositivos reais.
38	    const score = (ip: string) => {
39	      if (/^192\.168\./.test(ip)) return 0;
40	      if (/^10\./.test(ip)) return 1;
41	      if (/^172\.(1[6-9]|2\d|3[01])\./.test(ip)) return 99; // virtual — vai por último
42	      return 2;
43	    };
44	    const ips = todos.sort((a, b) => score(a) - score(b));
45	
46	    const { data } = await this.supabase.client
47	      .from('platform_settings')
48	      .select('config')
49	      .eq('id', 1)
50	      .maybeSingle();
51	    const cfg = ((data?.config ?? {}) as Record<string, any>);
52	    return {
53	      lan_ips: ips,
54	      porta: 4028,
55	      cloudflare_domain: cfg.cloudflare_domain || null,
56	    };
57	  }
58	
59	  @Get()
60	  async listarRestaurantes(
61	    @Query()
62	    query: {
63	      state?: string;
64	      city?: string;
65	      neighborhood?: string;
66	      cep?: string;
67	      lat?: string;
68	      lng?: string;
69	      raio_km?: string;
70	    },
71	    @Headers('authorization') authorization?: string,
72	  ) {
73	    // Sem Authorization o resultado é puramente função da querystring — cacheável.
74	    // Com Authorization pode depender do endereço salvo do cliente (personalizado), então
75	    // nesse caso sempre busca direto no Supabase, igual já fazia antes do cache.
76	    const cacheKey = !authorization
77	      ? `catalogo:home:${JSON.stringify(query, Object.keys(query).sort())}`
78	      : null;
79	
80	    if (cacheKey) {
81	      const cached = await this.redis.getJSON<{ restaurantes: any[] }>(cacheKey);
82	      if (cached) return cached;
83	    }
84	
85	    let q = this.supabase.client
86	      .from('restaurants')
87	      .select('id, name, address, state, city, neighborhood, cep, logo_url, slug, aparencia, frete_motoboy, lat, lng')
88	      .not('slug', 'is', null)
89	      .eq('bloqueado', false);
90	
91	    if (query.state) q = q.ilike('state', query.state);
92	    if (query.city) q = q.ilike('city', query.city);
93	    if (query.neighborhood) q = q.ilike('neighborhood', query.neighborhood);
94	    if (query.cep) q = q.ilike('cep', `${query.cep.replace(/\D/g, '').slice(0, 5)}%`);
95	
96	    const { data, error } = await q.order('name');
97	    if (error) throw error;
98	
99	    let restaurantes = data ?? [];
100	
101	    // Filtro/ordenação por proximidade — GPS ao vivo do navegador é a fonte principal
102	    // (comportamento esperado: cliente abre o site, mostra estabelecimentos perto de onde
103	    // ele está agora). Só cai pro endereço salvo/geocodificado do perfil (ver PerfilService)
104	    // quando o navegador não mandou lat/lng (GPS negado/indisponível) e o cliente tem token
105	    // válido — nunca confia numa coordenada de "fallback" vinda do próprio client.
106	    let lat = query.lat ? parseFloat(query.lat) : null;
107	    let lng = query.lng ? parseFloat(query.lng) : null;
108	    let usandoEnderecoSalvo = false;
109	
110	    if (lat == null && lng == null && authorization?.startsWith('Bearer ')) {
111	      const token = authorization.slice('Bearer '.length);
112	      const payload = await this.supabaseJwt.verificar(token);
113	      if (payload?.sub) {
114	        const { data: customer } = await this.supabase.client
115	          .from('customers')
116	          .select('lat, lng')
117	          .eq('user_id', payload.sub)
118	          .maybeSingle();
119	        if (customer?.lat != null && customer?.lng != null) {
120	          lat = customer.lat;
121	          lng = customer.lng;
122	          usandoEnderecoSalvo = true;
123	        }
124	      }
125	    }
126	
127	    if (lat != null && lng != null && !Number.isNaN(lat) && !Number.isNaN(lng)) {
128	      const raioKm = query.raio_km ? parseFloat(query.raio_km) : (usandoEnderecoSalvo ? RAIO_KM_PADRAO : null);
129	      restaurantes = restaurantes
130	        .map((r) => ({
131	          ...r,
132	          // 3 casas decimais (precisão de metro) — raios pequenos (20m, 50m...)
133	          // precisavam de mais que os 100m que 1 casa decimal dava.
134	          distancia_km:
135	            r.lat != null && r.lng != null
136	              ? Math.round(haversineKm({ lat, lng }, { lat: r.lat, lng: r.lng }) * 1000) / 1000
137	              : null,
138	        }))
139	        .filter((r) => raioKm == null || (r.distancia_km != null && r.distancia_km <= raioKm))
140	        .sort((a, b) => (a.distancia_km ?? Infinity) - (b.distancia_km ?? Infinity));
141	    }
